   103				return
   104			}
   105			defer in.Close()
   106	
   107			out, err := net.Dial("tcp", t.URL.Host)
   108			if err != nil {
   109				c.Set("_error", echo.NewHTTPError(http.StatusBadGateway, fmt.Sprintf("proxy raw, dial error=%v, url=%s", t.URL, err)))
   110				return
   111			}
   112			defer out.Close()
   113	
   114			// Write header
   115			err = r.Write(out)
   116			if err != nil {
